# Canvas LMS Integration
import requests

CANVAS_API_KEY = "4bb5b288bb301d3d4a691ebff686fc67ad49daa8"
CANVAS_URL = "https://your-institution.instructure.com"

def get_canvas_courses():
    """Get all courses"""
    response = requests.get(
        f"{CANVAS_URL}/api/v1/courses",
        headers={"Authorization": f"Bearer {CANVAS_API_KEY}"}
    )
    return response.json()

def create_assignment(course_id, name, points_possible):
    """Create assignment in course"""
    response = requests.post(
        f"{CANVAS_URL}/api/v1/courses/{course_id}/assignments",
        headers={"Authorization": f"Bearer {CANVAS_API_KEY}"},
        json={
            "assignment": {
                "name": name,
                "points_possible": points_possible,
                "submission_types": ["online_text_entry"]
            }
        }
    )
    return response.json()
